#!/bin/sh
# shellcheck disable=SC2016 # $1/$2 in the single-quoted "sh -c" strings expand inside the container
# Container checks for agent/vantage-agent.sh. Not part of `bun test` (needs a local Docker); run:
#
#   sh test/fixtures/agent/docker-check.sh
#
# Per image:
#   - central mode: the script piped into "sh -s -- --print", exactly as ops runs it over SSH; the
#     report is validated on the host with the server parser (check-report.ts)
#   - with curl: agent mode against the stub on the host (valid token -> report accepted, wrong
#     token -> exit 1) and the ES check; without curl: the clear "curl not found" failure
#   - --install twice and --uninstall twice as root (cron.d when present, else the root crontab;
#     /etc/cron.d is created when the image has neither)
# Every container gets a bind-mounted file (/etc/somefile.conf) that shares its device with a
# bind-mounted directory listed after it (/srv/data), an anonymous volume at a path with a space
# (/mnt/space dir, same device as the /etc/hosts file mounts) and a tmpfs (/scratch).
#
# Images must exist locally; nothing is pulled. Environment:
#   IMAGES     space-separated images (default: debian:stable-slim alpine:latest dvtest-backend:latest
#              nginx:alpine; missing ones are skipped)
#   STUB_HOST  bind address of the host stub (default 127.0.0.1, which Docker Desktop forwards to
#              host.docker.internal; on Linux use the docker0 address, e.g. 172.17.0.1)
set -u

HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/../../.." && pwd)
AGENT=$ROOT/agent/vantage-agent.sh
IMAGES=${IMAGES:-debian:stable-slim alpine:latest dvtest-backend:latest nginx:alpine}
STUB_HOST=${STUB_HOST:-127.0.0.1}
TOKEN=vha_$(printf '%043d' 0 | tr 0 D)
WRONG_TOKEN=vha_$(printf '%043d' 0 | tr 0 W)

WORK=$(mktemp -d "${TMPDIR:-/tmp}/vantage-agent-docker.XXXXXX") || exit 1
STUB_PID=''
FAILED=0
cleanup() {
  if [ -n "$STUB_PID" ]; then kill "$STUB_PID" 2>/dev/null; fi
  rm -rf "$WORK"
}
trap cleanup EXIT
trap 'exit 130' INT TERM

pass() { printf '  ok    %s\n' "$*"; }
fail() {
  printf '  FAIL  %s\n' "$*"
  FAILED=1
}
indent() { sed 's/^/    | /'; }

command -v docker >/dev/null 2>&1 || {
  echo "docker not found" >&2
  exit 2
}
command -v bun >/dev/null 2>&1 || {
  echo "bun not found" >&2
  exit 2
}

# --- host stub ---------------------------------------------------------------------------------------
STUB_HOST=$STUB_HOST STUB_TOKEN=$TOKEN bun "$HERE/stub.ts" >"$WORK/port" 2>"$WORK/stub.log" &
STUB_PID=$!
i=0
while [ ! -s "$WORK/port" ] && [ "$i" -lt 100 ]; do
  sleep 0.1
  i=$((i + 1))
done
PORT=$(head -n 1 "$WORK/port")
[ -n "$PORT" ] || {
  echo "stub did not start:" >&2
  cat "$WORK/stub.log" >&2
  exit 2
}
STUB_LOCAL=http://127.0.0.1:$PORT
STUB_URL=http://host.docker.internal:$PORT
echo "stub on $STUB_HOST:$PORT, containers use $STUB_URL"

# --- container fixtures ------------------------------------------------------------------------------
mkdir -p "$WORK/data"
echo "somefile" >"$WORK/somefile.conf"
cat >"$WORK/in-container.sh" <<'EOF'
#!/bin/sh
# Generated by docker-check.sh: --install / --uninstall as root inside the container.
URL=$1 TOKEN=$2 HAS_CURL=$3
F=0
ok() { printf '  ok    %s\n' "$*"; }
bad() { printf '  FAIL  %s\n' "$*"; F=1; }
check() { _d=$1; shift; if "$@"; then ok "$_d"; else bad "$_d"; fi; }
mode() { stat -c %a "$1" 2>/dev/null; }
ours() { crontab -l 2>/dev/null | grep -c 'managed by vantage-agent'; }
others() { crontab -l 2>/dev/null | grep -vc 'managed by vantage-agent'; }

if [ -d /etc/cron.d ]; then CRON=cron.d
elif command -v crontab >/dev/null 2>&1; then CRON=crontab
else mkdir -p /etc/cron.d; CRON=cron.d; fi
echo "  cron mechanism: $CRON"
HAVE_CRONTAB=no
if command -v crontab >/dev/null 2>&1; then HAVE_CRONTAB=yes; OTHERS_BEFORE=$(others); fi

cp /opt/vantage/vantage-agent.sh /root/vantage-agent.sh
for i in 1 2; do
  sh /root/vantage-agent.sh --install --url "$URL" --token "$TOKEN" --interval 15 >/tmp/install.out 2>&1
  rc=$?
  if [ "$HAS_CURL" = yes ]; then
    check "install #$i exits 0" [ "$rc" = 0 ]
    check "install #$i sent the first report" grep -q 'first report sent' /tmp/install.out
  else
    check "install #$i without curl exits 1" [ "$rc" = 1 ]
    check "install #$i says curl not found" grep -q 'curl not found' /tmp/install.out
  fi
done
indent() { sed 's/^/    | /'; }
indent </tmp/install.out
check "binary mode 755" [ "$(mode /usr/local/bin/vantage-agent)" = 755 ]
check "config mode 600" [ "$(mode /etc/vantage-agent.conf)" = 600 ]
if [ "$CRON" = cron.d ]; then
  check "cron.d file mode 644" [ "$(mode /etc/cron.d/vantage-agent)" = 644 ]
  check "cron.d has exactly one job line" [ "$(grep -c 'vantage-agent --config' /etc/cron.d/vantage-agent)" = 1 ]
  check "cron.d job line as expected" grep -qx '\*/15 \* \* \* \* root /usr/local/bin/vantage-agent --config /etc/vantage-agent.conf >/dev/null 2>&1' /etc/cron.d/vantage-agent
  indent </etc/cron.d/vantage-agent
else
  check "crontab has our line exactly once" [ "$(ours)" = 1 ]
  check "other crontab lines kept" [ "$(others)" = "$OTHERS_BEFORE" ]
  crontab -l | indent
fi
(. /etc/vantage-agent.conf && [ "$VANTAGE_URL" = "$URL" ] && [ "$VANTAGE_TOKEN" = "$TOKEN" ])
check "config sources back to URL and token" [ $? = 0 ]
check "installed binary runs" /usr/local/bin/vantage-agent --version
/usr/local/bin/vantage-agent --uninstall >/tmp/un.out 2>&1
check "uninstall exits 0" [ $? = 0 ]
check "binary removed" [ ! -e /usr/local/bin/vantage-agent ]
check "config removed" [ ! -e /etc/vantage-agent.conf ]
check "cron.d file removed" [ ! -e /etc/cron.d/vantage-agent ]
if [ "$HAVE_CRONTAB" = yes ]; then
  check "no crontab line left" [ "$(ours)" = 0 ]
  check "other crontab lines still there" [ "$(others)" = "$OTHERS_BEFORE" ]
fi
sh /root/vantage-agent.sh --uninstall >/tmp/un2.out 2>&1
check "second uninstall exits 0" [ $? = 0 ]
check "second uninstall has nothing to remove" grep -q 'nothing to remove' /tmp/un2.out
exit $F
EOF

# Escaping with the image's own awk: a mounts table (VANTAGE_PROC) whose mount point holds a quote,
# a backslash (\134) and spaces (\040), and whose device holds a quote and a backslash.
cat >"$WORK/escape-check.sh" <<'EOF'
#!/bin/sh
mkdir -p /tmp/vp '/tmp/odd "q" \b'
cp /proc/meminfo /proc/loadavg /tmp/vp/
printf '%s\n' '/dev/vdz9 /tmp/odd\040"q"\040\134b ext4 rw 0 0' 'dev"q\134x /etc ext4 rw 0 0' >/tmp/vp/mounts
VANTAGE_PROC=/tmp/vp sh /opt/vantage/vantage-agent.sh --print
EOF

# drun IMAGE ARGS...: throwaway container (entrypoint sh) with the fixture mounts.
drun() {
  _img=$1
  shift
  docker run --rm -i --pull=never --entrypoint sh --add-host=host.docker.internal:host-gateway \
    -v "$WORK/somefile.conf:/etc/somefile.conf:ro" \
    -v "$WORK/data:/srv/data" \
    -v "/mnt/space dir" \
    --tmpfs /scratch \
    -v "$AGENT:/opt/vantage/vantage-agent.sh:ro" \
    -v "$WORK/in-container.sh:/opt/vantage/in-container.sh:ro" \
    -v "$WORK/escape-check.sh:/opt/vantage/escape-check.sh:ro" \
    "$_img" "$@"
}

reports() { curl -s "$STUB_LOCAL/__reports"; }

# --- per image ---------------------------------------------------------------------------------------
for img in $IMAGES; do
  echo
  if ! docker image inspect "$img" >/dev/null 2>&1; then
    echo "== $img: not available locally, skipped"
    continue
  fi
  info=$(drun "$img" -c '. /etc/os-release 2>/dev/null; printf "%s %s, sh=%s, awk=%s, curl=%s" "${ID:-?}" "${VERSION_ID:-?}" "$(readlink -f /bin/sh)" "$(readlink -f "$(command -v awk)")" "$(command -v curl >/dev/null 2>&1 && echo yes || echo no)"' </dev/null)
  echo "== $img ($info)"
  case $info in *curl=yes) has_curl=yes ;; *) has_curl=no ;; esac

  # central mode, exactly as over SSH
  drun "$img" -s -- --print <"$AGENT" >"$WORK/print.json" 2>"$WORK/print.err"
  rc=$?
  if [ "$rc" = 0 ] && [ ! -s "$WORK/print.err" ]; then pass "sh -s -- --print exits 0, no stderr"; else
    fail "sh -s -- --print: exit $rc"
    indent <"$WORK/print.err"
  fi
  if bun "$HERE/check-report.ts" --has-mount /srv/data --has-mount "/mnt/space dir" --no-mount /etc/somefile.conf \
    --no-mount /etc/hosts --no-mount /scratch --memory set <"$WORK/print.json" >"$WORK/check.out" 2>&1; then
    pass "report valid, bind-mounted file and tmpfs excluded, dir and space path reported"
  else
    fail "report check"
  fi
  indent <"$WORK/check.out"

  if drun "$img" /opt/vantage/escape-check.sh </dev/null |
    bun "$HERE/check-report.ts" --has-mount '/tmp/odd "q" \b' --has-mount /etc >"$WORK/check.out" 2>&1; then
    pass "quote, backslash and space in mount and device decoded and JSON-escaped"
  else
    fail "escaping"
    indent <"$WORK/check.out"
  fi

  if [ "$has_curl" = yes ]; then
    before=$(reports)
    drun "$img" -c 'VANTAGE_URL=$1 VANTAGE_TOKEN=$2 sh /opt/vantage/vantage-agent.sh' sh "$STUB_URL" "$TOKEN" </dev/null >"$WORK/post.out" 2>&1
    rc=$?
    after=$(reports)
    if [ "$rc" = 0 ] && [ "$after" = $((before + 1)) ]; then pass "agent mode posted one report"; else
      fail "agent mode: exit $rc, reports $before -> $after"
      indent <"$WORK/post.out"
    fi
    if curl -s "$STUB_LOCAL/__last-report" | bun "$HERE/check-report.ts" >/dev/null 2>&1; then pass "posted report valid"; else fail "posted report invalid"; fi

    drun "$img" -c 'sh /opt/vantage/vantage-agent.sh --url "$1" --token "$2"' sh "$STUB_URL" "$WRONG_TOKEN" </dev/null >"$WORK/post.out" 2>&1
    rc=$?
    if [ "$rc" = 1 ] && grep -q 401 "$WORK/post.out"; then pass "wrong token: exit 1 with the 401 on stderr"; else
      fail "wrong token: exit $rc"
      indent <"$WORK/post.out"
    fi

    if drun "$img" -c 'sh /opt/vantage/vantage-agent.sh --print --es-url "$1"' sh "$STUB_URL" </dev/null |
      bun "$HERE/check-report.ts" --es true/2/96 >"$WORK/check.out" 2>&1; then pass "es: reachable, 2 blocked indices, max disk 96"; else
      fail "es check"
      indent <"$WORK/check.out"
    fi
  else
    drun "$img" -c 'sh /opt/vantage/vantage-agent.sh --url "$1" --token "$2"' sh "$STUB_URL" "$TOKEN" </dev/null >"$WORK/post.out" 2>&1
    rc=$?
    if [ "$rc" = 1 ] && grep -q 'curl not found' "$WORK/post.out"; then pass "agent mode without curl: exit 1, says curl not found"; else
      fail "agent mode without curl: exit $rc"
      indent <"$WORK/post.out"
    fi
  fi

  if drun "$img" /opt/vantage/in-container.sh "$STUB_URL" "$TOKEN" "$has_curl" </dev/null >"$WORK/install.out" 2>&1; then
    cat "$WORK/install.out"
  else
    cat "$WORK/install.out"
    fail "install / uninstall checks"
  fi
done

echo
if [ "$FAILED" = 0 ]; then echo "docker-check: all passed"; else echo "docker-check: FAILURES"; fi
exit "$FAILED"
